def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 5:
        return 'C'
    if n == 99:
        return 'D'

    opp_coops = sum(1 for _, o in history if o == 'C')
    opp_coop_rate = opp_coops / n
    last_me, last_opp = history[-1]

    # Periodic probe against very cooperative opponents
    if opp_coop_rate > 0.9 and n > 10 and n % 10 == 0 and n < 95:
        return 'D'

    # Consecutive opponent defections
    consec_opp_def = 0
    for _, o in reversed(history):
        if o == 'D':
            consec_opp_def += 1
        else:
            break

    if consec_opp_def >= 3:
        return 'D'

    if last_opp == 'D' and last_me == 'C':
        if opp_coop_rate > 0.6:
            return 'C'
        return 'D'

    if last_opp == 'C' and last_me == 'D':
        return 'C'

    if opp_coop_rate > 0.85:
        return 'C'

    if opp_coop_rate < 0.3:
        return 'D'

    recent_len = min(10, n)
    recent = history[-recent_len:]
    recent_opp_coops = sum(1 for _, o in recent if o == 'C')
    recent_rate = recent_opp_coops / recent_len

    if recent_rate < opp_coop_rate - 0.3 and recent_len >= 5:
        return 'D'
    if recent_rate > opp_coop_rate + 0.3 and recent_len >= 5:
        return 'C'

    if n > 80:
        if opp_coop_rate < 0.5:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if rng.random() < 0.1 and opp_coop_rate > 0.5:
            return 'C'
        return 'D'

    return 'C'
